<section class="panel admin-form"><h2><?= $record?'编辑区域':'新增区域' ?></h2><form method="post" class="stack-form"><?= csrfField() ?><input type="hidden" name="id" value="<?= (int)$v('id',0) ?>"><div class="form-grid"><label>所属城市<select name="city_id" required><option value="">请选择城市</option><?php foreach(cityList(false) as $city): ?><option value="<?= $city['id'] ?>" <?= (int)$v('city_id',(int)getValue('city'))===(int)$city['id']?'selected':'' ?>><?= e($city['name']) ?><?= !$city['enabled']?'（停用）':'' ?></option><?php endforeach ?></select></label><label>区域名称<input name="name" value="<?= e($v('name')) ?>" maxlength="32" required></label><label>排序<input type="number" name="sort_order" value="<?= (int)$v('sort_order',0) ?>"><small class="field-help">数字越小，前台区域链接越靠前</small></label><label>状态<select name="enabled"><option value="1" <?= (int)$v('enabled',1)===1?'selected':'' ?>>启用</option><option value="0" <?= (int)$v('enabled',1)===0?'selected':'' ?>>停用</option></select></label></div><p class="field-help">区域生成独立的拼音URL；超过24个字符使用首拼加编号。名称修改后URL保持固定；停用时区域链接及其中的信息暂停展示。已创建区域不可迁移到其他城市。</p><div class="form-actions"><button class="button">保存区域</button><?php if($record): ?><a class="text-link" href="<?= e(listUrl(['city'=>$record['city_id'],'district'=>$record['id']])) ?>" target="_blank" rel="noopener">查看前台页面</a><?php endif ?></div></form></section>
<section class="panel table-panel"><div class="section-heading district-toolbar"><h2>城市区域</h2><form method="get" action="<?= e(adminUrl()) ?>"><input type="hidden" name="section" value="districts"><label>按城市查看 <select name="city"><option value="0">全部城市</option><?php foreach(cityList(false) as $city): ?><option value="<?= $city['id'] ?>" <?= (int)getValue('city')===(int)$city['id']?'selected':'' ?>><?= e($city['name']) ?></option><?php endforeach ?></select></label> <button class="button button-outline small">查看</button></form></div><div class="table-scroll"><table class="district-table"><thead><tr><th>城市</th><th>区域</th><th>前台URL</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= e($item['city_name']) ?></td><td><?= e($item['name']) ?></td><td><a class="accent-link" href="<?= e(listUrl(['city'=>$item['city_id'],'district'=>$item['id']])) ?>" target="_blank" rel="noopener"><?= e(collectionSlug($item)) ?></a></td><td><?= $item['sort_order'] ?></td><td><?= $item['enabled']?'启用':'停用' ?></td><td><div class="table-actions"><a href="<?= e(adminUrl('districts',['edit'=>$item['id'],'city'=>getValue('city')])) ?>">编辑</a><form method="post" data-confirm="确定删除区域？被信息引用的区域不能删除，可改为停用。"><?= csrfField() ?><input type="hidden" name="id" value="<?= $item['id'] ?>"><input type="hidden" name="action" value="delete"><button class="text-button danger">删除</button></form></div></td></tr><?php endforeach ?></tbody></table></div><?php if(!$items): ?><p class="empty">暂无区域，可在上方新增。</p><?php endif ?></section>
